import{_ as l,a0 as o,w as s,s as p,ao as d,I as a,x as e,a1 as i,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"撰寫有效的技術簡歷的 7 個技巧 | LCTT x X-CMD","titleTemplate":false,"description":"撰寫有效的技術簡歷的 7 個技巧 | LCTT (202003) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"撰寫有效的技術簡歷的 7 個技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"撰寫有效的技術簡歷的 7 個技巧 | LCTT (202003) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202003/20200225 7 tips for writing an effective technical resume","title":"撰寫有效的技術簡歷的 7 個技巧","tag":"202003","desc":""},"relativePath":"202003/20200225 7 tips for writing an effective technical resume.md","filePath":"[post].md"}'),f={name:"202003/20200225 7 tips for writing an effective technical resume.md"};function u(m,t,h,b,g,x){const r=o("Link");return s(),p("div",null,[t[18]||(t[18]=d('<h1 id="撰寫有效的技術簡歷的-7-個技巧" tabindex="-1">撰寫有效的技術簡歷的 7 個技巧 <a class="header-anchor" href="#撰寫有效的技術簡歷的-7-個技巧" aria-label="Permalink to “撰寫有效的技術簡歷的 7 個技巧”">​</a></h1><blockquote><p>遵循以下這些要點，把自己最好的一面呈現給潛在僱主。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202003/21/092248u2w2gz2aezre2ba2.jpg" alt=""></p><p>如果你是一名軟件工程師或技術領域的經理，那麼創建或更新簡歷可能是一項艱鉅的任務。要考慮的重點是什麼？應該怎麼把控格式、內容以及求職目標或摘要？哪些工作經驗相關？如何確保自動化招聘工具不會過濾掉你的簡歷？</p><p>在過去的七年中，作為一名招聘經理，我看到了各種各樣的簡歷；儘管有些令人印象深刻，但還有很多人寫的很糟糕。</p><p>在編寫或更新簡歷時，請遵循以下七個簡單原則。</p><h3 id="_1、概述" tabindex="-1">1、概述 <a class="header-anchor" href="#_1、概述" aria-label="Permalink to “1、概述”">​</a></h3><p>簡歷頂部的簡短段落應簡潔明瞭、目的明確，避免過度使用形容詞和副詞。諸如“令人印象深刻”、“廣泛”和“卓越”之類的詞，這些詞不會增加你的招聘機會；相反，它們看起來和感覺上像是過度使用的填充詞。 關於你的求職目標，問自己一個重要的問題：<strong>它是否告訴招聘經理我正在尋找什麼樣的工作以及如何為他們提供價值？</strong> 如果不是，請加強並簡化它以回答該問題，或者將其完全排除在外。</p><h3 id="_2、工作經驗" tabindex="-1">2、工作經驗 <a class="header-anchor" href="#_2、工作經驗" aria-label="Permalink to “2、工作經驗”">​</a></h3><p>數字、數字、數字——重要的事情説三遍。用確鑿的事實傳達觀點遠比一般的陳述，例如“幫助構建、管理、交付許多對客户利潤有貢獻的項目”更能對你有幫助。你的表達中應包括統計數據，例如“直接影響了 5 個頂級銀行的項目，這些項目將其上市時間縮短了 40％”，你提交了多少行代碼或管理了幾個團隊。數據比修飾語更能有效地展示你的能力和價值。</p><p>如果你經驗不足，沒有什麼工作經驗可展示，那些無關的經驗，如暑期兼職工作，就不要寫了。相反，將相關經驗的細節以及你所學到的知識的詳細信息寫進簡歷，這些可以使你成為一個更好的候選人。</p><h3 id="_3、搜索術語和行話" tabindex="-1">3、搜索術語和行話 <a class="header-anchor" href="#_3、搜索術語和行話" aria-label="Permalink to “3、搜索術語和行話”">​</a></h3><p>隨着技術在招聘過程中發揮如此巨大的作用，確保簡歷被標記為正確的職位非常重要，但不要在簡歷上過分吹噓自己。如果你提到敏捷技能但不知道看板是什麼，請三思。如果你提到自己精通 Java，但是已經有五年都沒有使用過 Java 了，請小心。如果存在你熟悉但不一定是當前在用的語言和框架，請創建其他類別或將你的經驗分為“精通”和“熟悉”。</p><h3 id="_4、教育" tabindex="-1">4、教育 <a class="header-anchor" href="#_4、教育" aria-label="Permalink to “4、教育”">​</a></h3><p>如果你不是應屆大學畢業生，那就沒必要再寫你的 GPA 或你參加過的俱樂部或兄弟會，除非你計劃將它們用作談話要點以在面試中贏得信任。確保將你發表的或獲取過專利的東西包括在內，即使它與該工作無關。如果你沒有大學學位，請添加一個證書部分代替教育背景部分。如果你是軍人，請包括現役和預備役時間。</p><h3 id="_5、資質證書" tabindex="-1">5、資質證書 <a class="header-anchor" href="#_5、資質證書" aria-label="Permalink to “5、資質證書”">​</a></h3><p>除非你想重新進入之前離開的領域，否則不要寫過期的證書，例如，如果你曾經是一名人事經理，而現在正尋求動手編程的工作。如果你擁有與該領域不再相關的認證，就不要寫這些認證，因為這些可能會分散招聘者的注意力，使你的簡歷失去吸引力。利用你的 LinkedIn 個人資料為簡歷添加更多色彩，因為大多數人在面試之前都會閲讀你的簡歷和 LinkedIn 個人資料。</p><h3 id="_6、拼寫和語法" tabindex="-1">6、拼寫和語法 <a class="header-anchor" href="#_6、拼寫和語法" aria-label="Permalink to “6、拼寫和語法”">​</a></h3><p>讓其他人幫忙對你的簡歷校對一下。很多時候，我在簡歷中看到過拼寫錯誤的單詞，或者錯誤用詞，如“他們的”、“他們是”、“那些”。這些可以避免和修復的錯誤會產生負面影響。理想情況下，你的簡歷應用主動語態，但是如果這樣會使你感到不舒服，那麼就用過去時書寫 —— 最重要的是要始終保持一致。不正確的拼寫和語法會傳遞你要麼不是很在乎所申請的工作，要麼沒有足夠注意細節。</p><h3 id="_7、格式" tabindex="-1">7、格式 <a class="header-anchor" href="#_7、格式" aria-label="Permalink to “7、格式”">​</a></h3>',20)),a("p",null,[t[1]||(t[1]=e("確保你的簡歷是最新的並且富有吸引力，這是留下良好第一印象的簡便方法。確保格式一致，例如相同的頁邊距，相同的間距、大寫字母和顏色（將調色板保持在最低限度，不要花花綠綠）是簡歷寫作中最基本的部分，但有必要表明你對工作感到自豪，並重視自己的價值和未來的僱主。在適當的地方使用表格，以視覺吸引人的方式分配信息。如果支持的話，以 .pdf 和 .docx 格式上傳簡歷，然後用 Google Docs 導出為 .odt 格式，這樣可以在 LibreOffice 中輕鬆打開。這裏有一個我推薦的簡單的 Google 文檔",-1)),i(r,{href:"https://docs.google.com/document/d/1ARVyybC5qQEiCzUOLElwAdPpKOK0Qf88srr682eHdCQ/edit"},{default:n(()=>[...t[0]||(t[0]=[e("簡歷模板",-1)])]),_:1}),t[2]||(t[2]=e("。 你還可以支付少量費用（不到 10 美元）從一些設計公司購買模板。",-1))]),t[19]||(t[19]=a("h3",{id:"定期更新",tabindex:"-1"},[e("定期更新 "),a("a",{class:"header-anchor",href:"#定期更新","aria-label":"Permalink to “定期更新”"},"​")],-1)),t[20]||(t[20]=a("p",null,"如果你需要（或希望）申請一份工作，定期更新簡歷可以最大程度地減少壓力，也可以幫助你創建和維護更準確的簡歷版本。撰寫簡歷時，要有遠見，確保至少讓另外三個人對你的簡歷內容、拼寫和語法進行檢查。即使你是由公司招募或其他人推薦給公司的，面試官也可能只能通過簡歷來認識你，因此請確保它為你帶來良好的第一印象。",-1)),t[21]||(t[21]=a("p",null,"你還有其他提示要添加嗎？",-1)),t[22]||(t[22]=a("hr",null,null,-1)),a("p",null,[t[4]||(t[4]=e("via: ",-1)),i(r,{href:"https://opensource.com/article/20/2/technical-resume-writing"},{default:n(()=>[...t[3]||(t[3]=[e("https://opensource.com/article/20/2/technical-resume-writing",-1)])]),_:1})]),a("p",null,[t[9]||(t[9]=e("作者：",-1)),i(r,{href:"https://opensource.com/users/emily-brand"},{default:n(()=>[...t[5]||(t[5]=[e("Emily Brand",-1)])]),_:1}),t[10]||(t[10]=e(" 選題：",-1)),i(r,{href:"https://github.com/lujun9972"},{default:n(()=>[...t[6]||(t[6]=[e("lujun9972",-1)])]),_:1}),t[11]||(t[11]=e(" 譯者：",-1)),i(r,{href:"https://github.com/Morisun029"},{default:n(()=>[...t[7]||(t[7]=[e("Morisun029",-1)])]),_:1}),t[12]||(t[12]=e(" 校對：",-1)),i(r,{href:"https://github.com/wxy"},{default:n(()=>[...t[8]||(t[8]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[15]||(t[15]=e("本文由 ",-1)),i(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原創編譯，",-1)),i(r,{href:"https://linux.cn/"},{default:n(()=>[...t[14]||(t[14]=[e("Linux中國",-1)])]),_:1}),t[17]||(t[17]=e(" 榮譽推出",-1))])])}const P=l(f,[["render",u]]);export{k as __pageData,P as default};
